export function compileUnified(project,{onProgress=()=>{},signal}={}){
 const python=project.language==='micropython',worker=new Worker(new URL(python?'./unified-worker.js':'./esp-compiler-worker.js',import.meta.url),{type:'module'});
 return new Promise((resolve,reject)=>{let finished=false;const done=(e,r)=>{if(finished)return;finished=true;clearTimeout(timer);signal?.removeEventListener('abort',abort);worker.terminate();e?reject(e):resolve(r);};const abort=()=>done(new DOMException('İptal edildi.','AbortError')),timer=setTimeout(()=>done(Error('Derleme süre sınırı aşıldı.')),120000);signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted)return abort();worker.onmessage=({data:d})=>{if(d.progress)return onProgress(d.progress);if(d.type==='checked')return done(null,{format:'micropython',payload:project.code,flashBytes:0,staticRamBytes:0,stderr:[]});if(d.ok)return done(null,{format:isPico(project)?'pico-bin':isTiva(project)?'tiva-bin':isSTM(project)?'stm32-bin':'esp-bin',payload:encodeBytes(d.result.image),flashBytes:d.result.flashBytes??d.result.image.length,staticRamBytes:d.result.staticRamBytes||0,stderr:[d.result.log]});if(d.type==='error'||d.ok===false)done(Error(d.message||d.error));};worker.onerror=e=>done(Error(e.message));worker.postMessage(python?{type:'check',chip:boardKey(project),source:project.code,project}:{chip:boardKey(project),source:project.code,files:project.files||[],language:project.language||'arduino'});});
}
